import { test, describe } from "node:test";
import assert from "node:assert/strict";
import {
  RATING_SCALE,
  notchChange,
  notchCalculator,
} from "../../src/ratings/notch.mjs";

const EXPECTED_SCALE = [
  "AAA", "AA+", "AA", "AA-", "A+", "A", "A-",
  "BBB+", "BBB", "BBB-", "BB+", "BB", "BB-",
  "B+", "B", "B-", "CCC+", "CCC", "CCC-",
];

const INVALID_VALUES = [
  ["empty string", ""],
  ["blank string", "   "],
  ["internal space BBB +", "BBB +"],
  ["internal space B B", "B B"],
  ["D", "D"],
  ["SD", "SD"],
  ["NR", "NR"],
  ["CC", "CC"],
  ["AAA+", "AAA+"],
  ["CCC--", "CCC--"],
  ["Baa1", "Baa1"],
  ["null", null],
  ["undefined", undefined],
  ["number", 3],
  ["object", {}],
  ["array", ["BBB"]],
  ["object with toString", { toString() { return "BBB"; } }],
];

describe("RATING_SCALE", () => {
  test("AC-1: holds the 19 C1 ratings, best first, in a frozen array", () => {
    assert.deepEqual(RATING_SCALE, EXPECTED_SCALE);
    assert.equal(RATING_SCALE.length, 19);
    assert.equal(Array.isArray(RATING_SCALE), true);
    assert.equal(Object.isFrozen(RATING_SCALE), true);
  });

  test("AC-1: cannot be mutated", () => {
    assert.throws(() => RATING_SCALE.push("D"), TypeError);
    assert.equal(RATING_SCALE.length, 19);
    assert.equal(RATING_SCALE[18], "CCC-");
    assert.throws(() => {
      RATING_SCALE[0] = "X";
    }, TypeError);
    assert.equal(RATING_SCALE[0], "AAA");
  });
});

describe("notchChange", () => {
  test("AC-2: downgrades are positive", () => {
    assert.equal(notchChange("BBB+", "BB+"), 3);
    assert.equal(notchChange("BBB+", "BBB-"), 2);
    assert.equal(notchChange("BBB", "BBB-"), 1);
    assert.equal(notchChange("A", "BBB+"), 2);
    assert.equal(notchChange("AAA", "CCC-"), 18);
  });

  test("AC-3: upgrades are negative", () => {
    assert.equal(notchChange("BB", "BBB"), -3);
    assert.equal(notchChange("BBB-", "BBB"), -1);
    assert.equal(notchChange("A-", "A"), -1);
    assert.equal(notchChange("CCC-", "AAA"), -18);
  });

  test("AC-4: the same rating gives +0, never -0", () => {
    for (const r of ["BBB", "AAA", "CCC-"]) {
      assert.equal(Object.is(notchChange(r, r), 0), true, r);
    }
  });

  test("argument order matters", () => {
    assert.equal(notchChange("BBB", "BB"), 3);
    assert.equal(notchChange("BB", "BBB"), -3);
  });

  test("AC-5: ignores case and leading/trailing whitespace", () => {
    assert.equal(notchChange(" bbb+ ", "BB+"), 3);
    assert.equal(notchChange("\tBbB+\n", "bb+"), 3);
    assert.equal(Object.is(notchChange("aa-", "AA-"), 0), true);
    assert.equal(notchChange(" ccc- ", "AAA"), -18);
    assert.equal(notchChange(" BBB ", "BBB-"), 1);
  });

  for (const [name, value] of INVALID_VALUES) {
    test(`AC-6: throws RangeError for invalid ${name}`, () => {
      assert.throws(() => notchChange(value, "BBB"), RangeError);
      assert.throws(() => notchChange("BBB", value), RangeError);
    });
  }

  test("AC-6: throws RangeError for missing or doubly invalid arguments", () => {
    assert.throws(() => notchChange("BBB"), RangeError);
    assert.throws(() => notchChange(), RangeError);
    assert.throws(() => notchChange("D", "NR"), RangeError);
  });

  test("error message names the bad input", () => {
    assert.throws(() => notchChange("Baa1", "BBB"), /Baa1/);
  });
});

describe("notchCalculator", () => {
  const cases = [
    // AC-7
    ["BBB+", "BB+", { notches: 3, direction: "downgrade", wl: 2 }],
    ["AAA", "CCC-", { notches: 18, direction: "downgrade", wl: 2 }],
    ["AAA", "AA-", { notches: 3, direction: "downgrade", wl: 2 }],
    // AC-8
    ["BBB+", "BBB-", { notches: 2, direction: "downgrade", wl: 1 }],
    ["A", "BBB+", { notches: 2, direction: "downgrade", wl: 1 }],
    // AC-9
    ["BBB", "BBB-", { notches: 1, direction: "downgrade", wl: 0 }],
    ["CCC", "CCC-", { notches: 1, direction: "downgrade", wl: 0 }],
    // AC-10
    ["BB", "BBB", { notches: -3, direction: "upgrade", wl: 0 }],
    ["BBB-", "BBB", { notches: -1, direction: "upgrade", wl: 0 }],
    ["A-", "A", { notches: -1, direction: "upgrade", wl: 0 }],
    ["CCC-", "AAA", { notches: -18, direction: "upgrade", wl: 0 }],
    ["BBB-", "BBB+", { notches: -2, direction: "upgrade", wl: 0 }],
    ["BB+", "BBB+", { notches: -3, direction: "upgrade", wl: 0 }],
    // AC-11
    ["BBB", "BBB", { notches: 0, direction: "unchanged", wl: 0 }],
    ["AAA", "AAA", { notches: 0, direction: "unchanged", wl: 0 }],
    ["CCC-", "CCC-", { notches: 0, direction: "unchanged", wl: 0 }],
  ];

  for (const [previous, current, expected] of cases) {
    test(`${previous} -> ${current} gives ${JSON.stringify(expected)}`, () => {
      const result = notchCalculator(previous, current);
      assert.deepEqual(result, expected);
      assert.equal(Object.is(result.notches, expected.notches), true);
    });
  }

  test("AC-11: unchanged notches is +0, never -0", () => {
    for (const r of ["BBB", "AAA", "CCC-"]) {
      assert.equal(Object.is(notchCalculator(r, r).notches, 0), true, r);
    }
  });

  test("AC-5: ignores case and whitespace", () => {
    assert.deepEqual(notchCalculator("bbb+", "bb+"), {
      notches: 3,
      direction: "downgrade",
      wl: 2,
    });
    assert.deepEqual(notchCalculator(" bbb ", " BBB- "), {
      notches: 1,
      direction: "downgrade",
      wl: 0,
    });
  });

  test("AC-12: returns exactly the keys notches, direction, wl", () => {
    const result = notchCalculator("BBB+", "BB+");
    assert.deepEqual(Object.keys(result).sort(), ["direction", "notches", "wl"]);
  });

  test("notches equals notchChange", () => {
    assert.equal(notchCalculator("BB", "BBB").notches, notchChange("BB", "BBB"));
  });

  for (const [name, value] of INVALID_VALUES) {
    test(`AC-6: throws RangeError for invalid ${name}`, () => {
      assert.throws(() => notchCalculator(value, "BBB"), RangeError);
      assert.throws(() => notchCalculator("BBB", value), RangeError);
    });
  }

  test("AC-6: throws RangeError for missing or doubly invalid arguments", () => {
    assert.throws(() => notchCalculator("BBB"), RangeError);
    assert.throws(() => notchCalculator(), RangeError);
    assert.throws(() => notchCalculator("", null), RangeError);
  });
});

/**
 * Notch calculator for external ratings (REQ-06-02).
 * Pure functions, no I/O.
 */

/**
 * The 19 ratings of the C1 scale, best first (AAA = index 0, CCC- = index 18).
 * Frozen: mutation attempts throw TypeError in strict mode (ESM).
 * @type {ReadonlyArray<string>}
 */
export const RATING_SCALE = Object.freeze([
  "AAA", "AA+", "AA", "AA-", "A+", "A", "A-",
  "BBB+", "BBB", "BBB-", "BB+", "BB", "BB-",
  "B+", "B", "B-", "CCC+", "CCC", "CCC-",
]);

/**
 * Validates a rating and returns its index on RATING_SCALE.
 * Non-strings are rejected without coercion; strings are trimmed and upper-cased.
 * @param {unknown} value
 * @param {string} name argument name, used in the error message
 * @returns {number}
 * @throws {RangeError} if the value is not a string or not on the scale
 */
function scaleIndex(value, name) {
  if (typeof value !== "string") {
    throw new RangeError(
      `${name} must be a rating string, got ${describe(value)}`
    );
  }
  const index = RATING_SCALE.indexOf(value.trim().toUpperCase());
  if (index === -1) {
    throw new RangeError(`${name} is not on the rating scale: ${JSON.stringify(value)}`);
  }
  return index;
}

/**
 * @param {unknown} value
 * @returns {string}
 */
function describe(value) {
  if (value === null) return "null";
  if (Array.isArray(value)) return "array";
  return typeof value;
}

/**
 * Signed number of notches between two ratings: index(current) - index(previous).
 * A downgrade is positive, an upgrade negative, an unchanged rating +0.
 * Input is trimmed and case-folded.
 * @param {string} previous previous rating, e.g. "BBB+"
 * @param {string} current current rating, e.g. "BB+"
 * @returns {number}
 * @throws {RangeError} if either argument is not a string or not on RATING_SCALE
 */
export function notchChange(previous, current) {
  const from = scaleIndex(previous, "previous");
  const to = scaleIndex(current, "current");
  // "+ 0" turns a would-be -0 into +0.
  return to - from + 0;
}

/**
 * Notch change, its direction and the resulting Watchlist level (WL).
 * WL is 2 for a downgrade of 3 or more notches, 1 for exactly 2, otherwise 0.
 * @param {string} previous previous rating, e.g. "BBB+"
 * @param {string} current current rating, e.g. "BB+"
 * @returns {{ notches: number, direction: "downgrade" | "upgrade" | "unchanged", wl: 0 | 1 | 2 }}
 * @throws {RangeError} if either argument is not a string or not on RATING_SCALE
 */
export function notchCalculator(previous, current) {
  const notches = notchChange(previous, current);
  const direction = notches > 0 ? "downgrade" : notches < 0 ? "upgrade" : "unchanged";
  const wl = notches >= 3 ? 2 : notches === 2 ? 1 : 0;
  return { notches, direction, wl };
}

