import { test } from "node:test";
import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { existsSync, readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import path from "node:path";

import * as notchModule from "../../../src/ratings/notch.mjs";
import {
  RATING_SCALE,
  notchChange,
  notchCalculator,
} from "../../../src/ratings/notch.mjs";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..", "..", "..");
const SOURCE = path.join(ROOT, "src", "ratings", "notch.mjs");
const EXPECTED_SCALE = [
  "AAA", "AA+", "AA", "AA-", "A+", "A", "A-",
  "BBB+", "BBB", "BBB-", "BB+", "BB", "BB-",
  "B+", "B", "B-", "CCC+", "CCC", "CCC-",
];

function allPairs() {
  const pairs = [];
  for (const p of RATING_SCALE) for (const c of RATING_SCALE) pairs.push([p, c]);
  return pairs;
}

// ---------- AC-1 ----------
test("AC-1: RATING_SCALE is the frozen 19-rating C1 array, best first", () => {
  assert.deepEqual(RATING_SCALE, EXPECTED_SCALE);
  assert.equal(RATING_SCALE.length, 19);
  assert.equal(Array.isArray(RATING_SCALE), true);
  assert.equal(Object.isFrozen(RATING_SCALE), true);
});

test("AC-1: RATING_SCALE cannot be mutated (push / index assignment throw TypeError)", () => {
  assert.throws(() => RATING_SCALE.push("D"), TypeError);
  assert.equal(RATING_SCALE.length, 19);
  assert.equal(RATING_SCALE[18], "CCC-");
  assert.throws(() => {
    "use strict";
    RATING_SCALE[0] = "X";
  }, TypeError);
  assert.equal(RATING_SCALE[0], "AAA");
});

// ---------- AC-2 / AC-3 / AC-4 ----------
test("AC-2: notchChange on a downgrade is positive", () => {
  assert.equal(notchChange("BBB+", "BB+"), 3);
  assert.equal(notchChange("BBB+", "BBB-"), 2);
  assert.equal(notchChange("BBB", "BBB-"), 1);
  assert.equal(notchChange("A", "BBB+"), 2);
  assert.equal(notchChange("AAA", "CCC-"), 18);
  assert.equal(notchChange("AAA", "AA-"), 3);
  assert.equal(notchChange("CCC", "CCC-"), 1);
});

test("AC-3: notchChange on an upgrade is negative", () => {
  assert.equal(notchChange("BB", "BBB"), -3);
  assert.equal(notchChange("BBB-", "BBB"), -1);
  assert.equal(notchChange("A-", "A"), -1);
  assert.equal(notchChange("CCC-", "AAA"), -18);
  assert.equal(notchChange("BBB-", "BBB+"), -2);
  assert.equal(notchChange("BB+", "BBB+"), -3);
});

test("AC-4: notchChange of the same rating is +0, never -0", () => {
  for (const r of ["BBB", "AAA", "CCC-"]) {
    assert.equal(Object.is(notchChange(r, r), 0), true, r);
  }
});

test("AC-2/AC-3: argument order matters (BBB->BB = 3, BB->BBB = -3)", () => {
  assert.equal(notchChange("BBB", "BB"), 3);
  assert.equal(notchChange("BB", "BBB"), -3);
});

// ---------- AC-5 ----------
test("AC-5: notchChange trims whitespace and folds case", () => {
  assert.equal(notchChange(" bbb+ ", "BB+"), 3);
  assert.equal(notchChange("\tBbB+\n", "bb+"), 3);
  assert.equal(Object.is(notchChange("aa-", "AA-"), 0), true);
  assert.equal(notchChange(" ccc- ", "AAA"), -18);
  assert.equal(notchChange(" BBB ", "BBB-"), 1);
});

test("AC-5: notchCalculator trims whitespace and folds case", () => {
  assert.deepEqual(notchCalculator("bbb+", "bb+"), { notches: 3, direction: "downgrade", wl: 2 });
  assert.deepEqual(notchCalculator(" bbb ", " BBB- "), { notches: 1, direction: "downgrade", wl: 0 });
});

// ---------- AC-6 ----------
const INVALID_VALUES = [
  ["empty string", ""],
  ["blank string", "   "],
  ["internal space 'BBB +'", "BBB +"],
  ["internal space 'B B'", "B B"],
  ["D", "D"],
  ["SD", "SD"],
  ["NR", "NR"],
  ["CC", "CC"],
  ["C", "C"],
  ["AAA+", "AAA+"],
  ["CCC--", "CCC--"],
  ["Baa1", "Baa1"],
  ["BBB+ (stable)", "BBB+ (stable)"],
  ["null", null],
  ["undefined", undefined],
  ["number 3", 3],
  ["object {}", {}],
  ["array ['BBB']", ["BBB"]],
  ["object with toString() -> 'BBB'", { toString() { return "BBB"; } }],
];

test("AC-6: notchChange throws RangeError for every invalid value in either position", () => {
  for (const [label, v] of INVALID_VALUES) {
    assert.throws(() => notchChange(v, "BBB"), RangeError, `previous=${label}`);
    assert.throws(() => notchChange("BBB", v), RangeError, `current=${label}`);
  }
});

test("AC-6: notchCalculator throws RangeError for every invalid value in either position", () => {
  for (const [label, v] of INVALID_VALUES) {
    assert.throws(() => notchCalculator(v, "BBB"), RangeError, `previous=${label}`);
    assert.throws(() => notchCalculator("BBB", v), RangeError, `current=${label}`);
  }
});

test("AC-6: missing or doubly invalid arguments throw RangeError", () => {
  assert.throws(() => notchChange("BBB"), RangeError);
  assert.throws(() => notchChange(), RangeError);
  assert.throws(() => notchCalculator("BBB"), RangeError);
  assert.throws(() => notchCalculator(), RangeError);
  assert.throws(() => notchChange("D", "NR"), RangeError);
  assert.throws(() => notchCalculator("", null), RangeError);
});

test("AC-6: non-breaking space is trimmed (trim strips U+00A0), still valid", () => {
  assert.equal(notchChange(" BBB ", "BBB-"), 1);
});

// ---------- AC-7 .. AC-11 ----------
test("AC-7: downgrade of 3+ notches gives WL 2", () => {
  assert.deepEqual(notchCalculator("BBB+", "BB+"), { notches: 3, direction: "downgrade", wl: 2 });
  assert.deepEqual(notchCalculator("AAA", "CCC-"), { notches: 18, direction: "downgrade", wl: 2 });
  assert.deepEqual(notchCalculator("AAA", "AA-"), { notches: 3, direction: "downgrade", wl: 2 });
});

test("AC-8: downgrade of exactly 2 notches gives WL 1", () => {
  assert.deepEqual(notchCalculator("BBB+", "BBB-"), { notches: 2, direction: "downgrade", wl: 1 });
  assert.deepEqual(notchCalculator("A", "BBB+"), { notches: 2, direction: "downgrade", wl: 1 });
