+/**
+ * Notch calculator for external ratings (REQ-06-02).
+ * Pure functions, no I/O.
+ */
+
+/**
+ * The 19 ratings of the C1 scale, best first (AAA = index 0, CCC- = index 18).
+ * Frozen: mutation attempts throw TypeError in strict mode (ESM).
+ * @type {ReadonlyArray<string>}
+ */
+export const RATING_SCALE = Object.freeze([
+  "AAA", "AA+", "AA", "AA-", "A+", "A", "A-",
+  "BBB+", "BBB", "BBB-", "BB+", "BB", "BB-",
+  "B+", "B", "B-", "CCC+", "CCC", "CCC-",
+]);
+
+/**
+ * Validates a rating and returns its index on RATING_SCALE.
+ * Non-strings are rejected without coercion; strings are trimmed and upper-cased.
+ * @param {unknown} value
+ * @param {string} name argument name, used in the error message
+ * @returns {number}
+ * @throws {RangeError} if the value is not a string or not on the scale
+ */
+function scaleIndex(value, name) {
+  if (typeof value !== "string") {
+    throw new RangeError(
+      `${name} must be a rating string, got ${describe(value)}`
+    );
+  }
+  const index = RATING_SCALE.indexOf(value.trim().toUpperCase());
+  if (index === -1) {
+    throw new RangeError(`${name} is not on the rating scale: ${JSON.stringify(value)}`);
+  }
+  return index;
+}
+
+/**
+ * @param {unknown} value
+ * @returns {string}
+ */
+function describe(value) {
+  if (value === null) return "null";
+  if (Array.isArray(value)) return "array";
+  return typeof value;
+}
+
+/**
+ * Signed number of notches between two ratings: index(current) - index(previous).
+ * A downgrade is positive, an upgrade negative, an unchanged rating +0.
+ * Input is trimmed and case-folded.
+ * @param {string} previous previous rating, e.g. "BBB+"
+ * @param {string} current current rating, e.g. "BB+"
+ * @returns {number}
+ * @throws {RangeError} if either argument is not a string or not on RATING_SCALE
+ */
+export function notchChange(previous, current) {
+  const from = scaleIndex(previous, "previous");
+  const to = scaleIndex(current, "current");
+  // Integer subtraction of equal values yields +0, never -0.
+  return to - from;
+}
+
+/**
+ * Notch change, its direction and the resulting Watchlist level (WL).
+ * WL is 2 for a downgrade of 3 or more notches, 1 for exactly 2, otherwise 0.
+ * @param {string} previous previous rating, e.g. "BBB+"
+ * @param {string} current current rating, e.g. "BB+"
+ * @returns {{ notches: number, direction: "downgrade" | "upgrade" | "unchanged", wl: 0 | 1 | 2 }}
+ * @throws {RangeError} if either argument is not a string or not on RATING_SCALE
+ */
+export function notchCalculator(previous, current) {
+  const notches = notchChange(previous, current);
+  const direction = notches > 0 ? "downgrade" : notches < 0 ? "upgrade" : "unchanged";
+  const wl = notches >= 3 ? 2 : notches === 2 ? 1 : 0;
+  return { notches, direction, wl };
+}
