import { test } from "node:test";
import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { existsSync, readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import path from "node:path";

import * as indicatorModule from "../../../src/indicators/countryRating.mjs";
import { countryRatingChangeWl } from "../../../src/indicators/countryRating.mjs";
import {
  RATING_SCALE,
  notchChange,
  notchCalculator,
} from "../../../src/ratings/notch.mjs";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..", "..", "..");
const SOURCE = path.join(ROOT, "src", "indicators", "countryRating.mjs");
const UNIT_TEST = path.join(ROOT, "test", "indicators", "countryRating.test.mjs");

// Guards against recursion: the bare `node --test` child discovers this very file.
const NESTED = "QA_T02_NESTED_RUN";

// A child `node --test` must not inherit the parent runner's reporter context.
function cleanEnv(extra = {}) {
  const env = { ...process.env, ...extra };
  delete env.NODE_TEST_CONTEXT;
  return env;
}

function allPairs() {
  const pairs = [];
  for (const p of RATING_SCALE) for (const c of RATING_SCALE) pairs.push([p, c]);
  return pairs;
}

function grep(pattern, ...files) {
  const res = spawnSync("grep", ["-nE", pattern, ...files], { encoding: "utf8" });
  assert.equal(res.error, undefined, "grep must be runnable");
  return res;
}

function counts(stdout) {
  const tests = /^# tests (\d+)$/m.exec(stdout);
  const fail = /^# fail (\d+)$/m.exec(stdout);
  assert.ok(tests, `no "# tests" line in output:\n${stdout}`);
  assert.ok(fail, `no "# fail" line in output:\n${stdout}`);
  return { tests: Number(tests[1]), fail: Number(fail[1]) };
}

// ---------- AC-13 / AC-14 / AC-15 / AC-5 / AC-6 / AC-17 through the public surface ----------
test("AC-13: one-notch downgrades give WL 1 (BBB>BBB-, AAA>AA+, CCC>CCC-)", () => {
  assert.equal(countryRatingChangeWl("BBB", "BBB-"), 1);
  assert.equal(countryRatingChangeWl("AAA", "AA+"), 1);
  assert.equal(countryRatingChangeWl("CCC", "CCC-"), 1);
});

test("AC-14: downgrades of 2+ notches give WL 2", () => {
  assert.equal(countryRatingChangeWl("BBB+", "BBB-"), 2);
  assert.equal(countryRatingChangeWl("A", "BBB+"), 2);
  assert.equal(countryRatingChangeWl("A-", "BBB"), 2);
  assert.equal(countryRatingChangeWl("BBB+", "BB+"), 2);
  assert.equal(countryRatingChangeWl("A-", "BB+"), 2);
  assert.equal(countryRatingChangeWl("AAA", "CCC-"), 2);
});

test("AC-15: upgrades and unchanged ratings give the number 0 (not -0, false, null)", () => {
  const cases = [
    ["BBB-", "BBB"], ["BB", "BBB"], ["CCC-", "AAA"], ["A", "A"],
    ["A-", "A"], ["BBB-", "BBB+"], ["AAA", "AAA"], ["CCC-", "CCC-"],
  ];
  for (const [p, c] of cases) {
    const wl = countryRatingChangeWl(p, c);
    assert.equal(Object.is(wl, 0), true, `(${p},${c}) -> ${String(wl)}`);
  }
});

test("AC-5: case and surrounding whitespace do not change the result", () => {
  assert.equal(countryRatingChangeWl(" bbb ", "bbb-"), 1);
  assert.equal(countryRatingChangeWl(" A-\t", "bb+"), 2);
  assert.equal(countryRatingChangeWl("aaa", "AAA"), 0);
});

const INVALID = [
  "", "   ", "BBB +", "B B",
  "D", "SD", "NR", "CC", "AAA+", "CCC--", "Baa1",
  null, undefined, 3, {}, ["BBB"],
];

test("AC-6: every invalid value in either position throws RangeError", () => {
  for (const v of INVALID) {
    assert.throws(() => countryRatingChangeWl(v, "BBB"), RangeError, `previous=${JSON.stringify(v)}`);
    assert.throws(() => countryRatingChangeWl("BBB", v), RangeError, `current=${JSON.stringify(v)}`);
  }
});

test("AC-6: missing and doubly invalid arguments throw RangeError", () => {
  assert.throws(() => countryRatingChangeWl("BBB"), RangeError);
  assert.throws(() => countryRatingChangeWl(), RangeError);
  assert.throws(() => countryRatingChangeWl("D", "NR"), RangeError);
});

test("AC-17: analyst-edited rating is just the current argument; arity 2, extra args ignored, no state", () => {
  assert.equal(countryRatingChangeWl("A-", "BB+"), 2);
  assert.equal(countryRatingChangeWl("A-", "BBB"), 2);
  assert.equal(countryRatingChangeWl.length, 2);
  assert.equal(countryRatingChangeWl("BBB", "BBB-", true), 1);
  assert.equal(countryRatingChangeWl("BBB", "BBB-", { wl: 0 }), 1);
  assert.deepEqual(
    [
      countryRatingChangeWl("A-", "BB+"),
      countryRatingChangeWl("BBB", "BBB"),
      countryRatingChangeWl("A-", "BB+"),
    ],
    [2, 0, 2]
  );
});

// ---------- QA criterion 10 (AC-16): source constraints ----------
test("AC-16: source imports notchChange from ../ratings/notch.mjs", () => {
  const res = grep(
    "import\\s*\\{[^}]*\\bnotchChange\\b[^}]*\\}\\s*from\\s*[\"']\\.\\./ratings/notch\\.mjs[\"']",
    SOURCE
  );
  assert.equal(res.status, 0, "expected at least one import match");
});

test("AC-16: source never mentions notchCalculator", () => {
  const res = grep("notchCalculator", SOURCE);
  assert.equal(res.status, 1, `unexpected matches: ${res.stdout}`);
});

test("AC-16: source has no rating literals anywhere (comments and JSDoc included)", () => {
  const res = grep("AAA|AA[+-]|BBB|BB[+-]|CCC|\\bA[+-]|\\bB[+-]", SOURCE);
  assert.equal(res.status, 1, `unexpected matches: ${res.stdout}`);
});

test("AC-16: source has no try/catch", () => {
  const res = grep("\\btry\\b|\\bcatch\\b", SOURCE);
  assert.equal(res.status, 1, `unexpected matches: ${res.stdout}`);
});

// ---------- QA criteria 11-14 (AC-16, AC-5): all 361 pairs ----------
test("AC-16: all 361 pairs return an integer in {0,1,2} equal to the notchChange threshold rule", () => {
  const pairs = allPairs();
  assert.equal(pairs.length, 361);
  for (const [p, c] of pairs) {
    const wl = countryRatingChangeWl(p, c);
    assert.equal(Number.isInteger(wl), true, `(${p},${c}) -> ${String(wl)}`);
    assert.ok(wl === 0 || wl === 1 || wl === 2, `(${p},${c}) -> ${wl}`);
    assert.equal(Object.is(wl, -0), false);
    const n = notchChange(p, c);
    const expected = n >= 2 ? 2 : n === 1 ? 1 : 0;
    assert.equal(wl, expected, `(${p},${c}) n=${n}`);
  }
});

test("AC-16: over 361 pairs WL 2 = 153, WL 1 = 18, WL 0 = 190", () => {
  const tally = { 0: 0, 1: 0, 2: 0 };
  for (const [p, c] of allPairs()) tally[countryRatingChangeWl(p, c)] += 1;
  assert.deepEqual(tally, { 0: 190, 1: 18, 2: 153 });
});

test("AC-16 (C6): differs from notchCalculator().wl on exactly 35 pairs (18 one-notch, 17 two-notch), equal on 326", () => {
  let oneNotch = 0;
  let twoNotch = 0;
  let equal = 0;
  let other = 0;
  for (const [p, c] of allPairs()) {
    const ind = countryRatingChangeWl(p, c);
    const calc = notchCalculator(p, c).wl;
    const n = notchChange(p, c);
    if (ind === calc) equal += 1;
    else if (n === 1 && ind === 1 && calc === 0) oneNotch += 1;
    else if (n === 2 && ind === 2 && calc === 1) twoNotch += 1;
    else other += 1;
  }
  assert.equal(oneNotch, 18);
  assert.equal(twoNotch, 17);
  assert.equal(other, 0);
  assert.equal(equal, 326);
  assert.equal(countryRatingChangeWl("BBB", "BBB-"), 1);
  assert.equal(notchCalculator("BBB", "BBB-").wl, 0);
});

test("AC-5: all 361 pairs with lowercase and padded input equal the canonical result", () => {
  for (const [p, c] of allPairs()) {
    assert.equal(
      countryRatingChangeWl(" " + p.toLowerCase(), c.toLowerCase() + " "),
      countryRatingChangeWl(p, c),
      `(${p},${c})`
    );
  }
});

// ---------- QA criteria 15, 16 (AC-18) ----------
test("AC-18: source has no I/O (grep for node:fs|node:http|node:net|fetch(|console.|process.std exits 1)", () => {
  const res = grep("node:fs|node:http|node:net|fetch\\(|console\\.|process\\.std", SOURCE);
