import { notchChange } from "../ratings/notch.mjs";

/**
 * Indicator 12 (REQ-03-12): Watchlist level for a country rating change.
 * Pure function, no I/O, no state. The notch count comes from the shared
 * notch calculation; validation is delegated to it and its error propagates.
 *
 * Thresholds: a downgrade of two or more notches gives 2, a downgrade of
 * exactly one notch gives 1, an upgrade or an unchanged rating gives 0.
 * Input is trimmed and case-folded by the shared notch calculation.
 *
 * @param {string} previous previous country rating
 * @param {string} current current country rating (as confirmed or edited by the caller)
 * @returns {0 | 1 | 2} Watchlist level
 * @throws {RangeError} if either argument is not a string or not on the rating scale
 */
export function countryRatingChangeWl(previous, current) {
  const notches = notchChange(previous, current);
  if (notches >= 2) return 2;
  if (notches === 1) return 1;
  return 0;
}
import { test } from "node:test";
import assert from "node:assert/strict";
import { countryRatingChangeWl } from "../../src/indicators/countryRating.mjs";
import { notchCalculator } from "../../src/ratings/notch.mjs";

const wl = countryRatingChangeWl;

test("AC-13: a 1-notch downgrade gives WL 1", () => {
  for (const [p, c] of [["BBB", "BBB-"], ["AAA", "AA+"], ["CCC", "CCC-"]]) {
    assert.equal(wl(p, c), 1, `${p} -> ${c}`);
  }
});

test("AC-13 (C6): differs from notchCalculator on a 1-notch downgrade", () => {
  assert.equal(wl("BBB", "BBB-"), 1);
  assert.equal(notchCalculator("BBB", "BBB-").wl, 0);
});

test("AC-14: a downgrade of 2 or more notches gives WL 2", () => {
  for (const [p, c] of [["BBB+", "BBB-"], ["A", "BBB+"], ["BBB+", "BB+"], ["AAA", "CCC-"]]) {
    assert.equal(wl(p, c), 2, `${p} -> ${c}`);
  }
});

test("AC-15: upgrade or unchanged gives the number 0", () => {
  const pairs = [
    ["BBB-", "BBB"], ["BB", "BBB"], ["CCC-", "AAA"], ["A", "A"],
    ["A-", "A"], ["BBB-", "BBB+"], ["AAA", "AAA"], ["CCC-", "CCC-"],
  ];
  for (const [p, c] of pairs) {
    assert.ok(Object.is(wl(p, c), 0), `${p} -> ${c}`);
  }
});

test("AC-5: case and surrounding whitespace are ignored", () => {
  assert.equal(wl(" bbb ", "bbb-"), 1);
  assert.equal(wl(" A-\t", "bb+"), 2);
  assert.equal(wl(" A-\t", "bb+"), 2);
  assert.equal(wl("aaa", "AAA"), 0);
});

const INVALID = [
  "", "   ", "BBB +", "B B",
  "D", "SD", "NR", "CC", "AAA+", "CCC--", "Baa1",
  null, undefined, 3, {}, ["BBB"],
];

test("AC-6: any invalid value in either position throws RangeError", () => {
  for (const v of INVALID) {
    assert.throws(() => wl(v, "BBB"), RangeError, `first: ${String(v)}`);
    assert.throws(() => wl("BBB", v), RangeError, `second: ${String(v)}`);
  }
});

test("AC-6: missing or doubly invalid arguments throw RangeError", () => {
  assert.throws(() => wl("BBB"), RangeError);
  assert.throws(() => wl(), RangeError);
  assert.throws(() => wl("D", "NR"), RangeError);
});

test("AC-17: analyst-edited ratings are graded from the caller's values", () => {
  assert.equal(wl("A-", "BB+"), 2);
  assert.equal(wl("A-", "BBB"), 2);
});

test("AC-17: arity is 2, extra arguments are ignored, no state", () => {
  assert.equal(wl.length, 2);
  assert.equal(wl("BBB", "BBB-", true), 1);
  assert.equal(wl("BBB", "BBB-", { wl: 0 }), 1);
  assert.deepEqual([wl("A-", "BB+"), wl("BBB", "BBB"), wl("A-", "BB+")], [2, 0, 2]);
});
